{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol, a lipophilic isoprenoid with a polar oxygenated ring, showed poor oral bioavailability in humans, supporting low F for the similarly lipophilic quinone-prenyl query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Synthetic lycopene dispersed in oil showed only about 1.2% of the dose appearing in blood circulation in humans, indicating that large lipophilic isoprenoids can have very low oral systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "In humans, all-trans lycopene bioavailability was 12.2 ± 2.1%, below the 20% threshold, providing quantified low-F evidence for a large lipophilic isoprenoid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene showed 58.5 ± 18.9% absolute bioavailability in humans, but this is a smaller acyclic C40 isoprenoid without the polar quinone head and is less transferable to the larger CoQ9 query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "13C-labeled all-trans lycopene reached 23.2 ± 8% bioavailability in healthy adults, showing that some lipophilic isoprenoids can exceed 20% under optimized labeled dosing conditions.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hyperforin showed high oral bioavailability in volunteers, but its smaller prenylated phloroglucinol scaffold is structurally distant from the long-chain ubiquinone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low because the query is a large, highly lipophilic ubiquinone-9; the closest transferable analogs with polar cyclic heads and isoprenoid tails (tocotrienol) and large lipophilic isoprenoids (lycopene) are predominantly below 20% F, while the high-F phytoene and hyperforin records are structurally less transferable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for CoQ9 or CoQ10 are present in the evidence set.",
    "Tocotrienol bioavailability is reported only qualitatively as poor, without a quantified F value.",
    "Lycopene bioavailability varies strongly with formulation and food matrix, making intrinsic absorption estimates uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

